// 边界递归拒重键，原序逐字段保留；形状不能代替M10完整军级入战和真实轮次回放。
#include "resident/checkpoint/checkpoint_decode_lifecycle.hpp"
#include "military_command_shock_codec.hpp"
#include "military_officer_codec.hpp"
#include "military_rout_contract.hpp"
#include "resident/storage/common_checkpoint.hpp"
#include <algorithm>
#include <set>
namespace hanmo::resident::military_command_shock_codec {
namespace {
using V=BoundaryValue;using D=V::Dict;using A=V::Array;
bool fields(FieldOrder current,FieldOrder expected){if(current.empty())return true;std::sort(current.begin(),current.end());std::sort(expected.begin(),expected.end());return current==expected;}
Status wire(const MilitaryCommandShockState& s){if(s.leaders.empty()||s.leaders.size()>64||s.causes.size()>s.leaders.size()||!fields(s.field_order,{"leaders","causes"}))return common_failure("MilitaryCommandShockShapeMismatch");for(const auto& l:s.leaders)if(l.army_id.empty()||l.actor_id.empty()||l.command_source.id.empty()||(l.command_source.kind!=MilitaryFieldCommandSourceKind::army_formation&&l.command_source.kind!=MilitaryFieldCommandSourceKind::field_assignment)||!fields(l.field_order,{"army_id","actor_id","unit_id","command_source"})||!fields(l.source_field_order,{"kind","id"}))return common_failure("MilitaryCommandShockLeaderShape",l.army_id);for(const auto& c:s.causes)if(c.army_id.empty()||c.actor_id.empty()||c.unit_id.empty()||c.round<1||c.round>10000||!fields(c.field_order,{"army_id","actor_id","unit_id","kind","round"}))return common_failure("MilitaryCommandShockCauseShape",c.army_id);return common_success();}
Status emit_row(ProjectionWriter& w,const MilitaryCommandShockLeader& l){w.field("army_id",l.army_id);w.field("actor_id",l.actor_id);w.field("unit_id",l.unit_id);w.object("command_source",l.source_field_order,[&](auto& c){c.field("kind",StableId(l.command_source.kind==MilitaryFieldCommandSourceKind::army_formation?"army_formation":"field_assignment"));return c.field("id",l.command_source.id);});w.order_fields(l.field_order);return w.status();}
Status emit_row(ProjectionWriter& w,const MilitaryCommandShockCause& c){w.field("army_id",c.army_id);w.field("actor_id",c.actor_id);w.field("unit_id",c.unit_id);w.field("kind",c.kind);w.field("round",c.round);w.order_fields(c.field_order);return w.status();}
void dec(const V& v,MilitaryCommandShockLeader& l,const StableId& p){boundary::fields(v,{"army_id","actor_id","unit_id","command_source"},{},p);l.field_order=boundary::order(v);l.army_id=boundary::get_string(v,"army_id",p);l.actor_id=boundary::get_string(v,"actor_id",p);l.unit_id=boundary::get_string(v,"unit_id",p);const auto& src=boundary::field(v,"command_source",p);boundary::fields(src,{"kind","id"},{},p+"/command_source");l.source_field_order=boundary::order(src);const auto kind=boundary::get_string(src,"kind",p);if(kind!="army_formation"&&kind!="field_assignment")boundary::fail("MilitaryCommandShockSourceKind",p);l.command_source={kind=="army_formation"?MilitaryFieldCommandSourceKind::army_formation:MilitaryFieldCommandSourceKind::field_assignment,boundary::get_string(src,"id",p)};}
void dec(const V& v,MilitaryCommandShockCause& c,const StableId& p){boundary::fields(v,{"army_id","actor_id","unit_id","kind","round"},{},p);c.field_order=boundary::order(v);c.army_id=boundary::get_string(v,"army_id",p);c.actor_id=boundary::get_string(v,"actor_id",p);c.unit_id=boundary::get_string(v,"unit_id",p);c.kind=boundary::get_string(v,"kind",p);c.round=boundary::get_int(v,"round",p);}
Status walk(CodecVisitor& v,MilitaryCommandShockLeader& l){v.field("army_id",l.army_id);v.field("actor_id",l.actor_id);v.field("unit_id",l.unit_id);Integer kind=static_cast<Integer>(l.command_source.kind);v.field("kind",kind);if(kind!=Integer(MilitaryFieldCommandSourceKind::army_formation)&&kind!=Integer(MilitaryFieldCommandSourceKind::field_assignment))return v.reject("MilitaryCommandShockSourceKind");if(v.reading())l.command_source.kind=static_cast<MilitaryFieldCommandSourceKind>(kind);v.field("id",l.command_source.id);common_checkpoint::strings(v,"source_field_order",l.source_field_order);common_checkpoint::strings(v,"field_order",l.field_order);return v.status();}
Status walk(CodecVisitor& v,MilitaryCommandShockCause& c){v.field("army_id",c.army_id);v.field("actor_id",c.actor_id);v.field("unit_id",c.unit_id);v.field("kind",c.kind);v.field("round",c.round);common_checkpoint::strings(v,"field_order",c.field_order);return v.status();}
}
Status emit_fields(ProjectionWriter& w,const MilitaryCommandShockState& s){auto checked=wire(s);if(!checked.ok)return checked;w.sequence("leaders",s.leaders,[](auto& c,const auto& r){return c.object("",[&](auto& row){return emit_row(row,r);});});w.sequence("causes",s.causes,[](auto& c,const auto& r){return c.object("",[&](auto& row){return emit_row(row,r);});});w.order_fields(s.field_order);return w.status();}
BoundaryValue encode(const MilitaryCommandShockState& s){BoundaryValue out;BoundaryProjectionWriter sink(out);auto checked=sink.object("",[&](auto& w){return emit_fields(w,s);});if(checked.ok)checked=sink.finish();if(!checked.ok)boundary::fail(checked.error.original.code,checked.error.original.path);return out;}
Outcome<MilitaryCommandShockState> decode(const BoundaryValue& value){try{auto unique=military_officer_codec::validate_json_unique_keys(value);if(!unique.ok)return {false,{},unique.error};boundary::fields(value,{"leaders","causes"},{},"command_shock");MilitaryCommandShockState s;s.field_order=boundary::order(value);for(const auto& l:boundary::array(boundary::field(value,"leaders","command_shock"),"leaders")){MilitaryCommandShockLeader r;dec(l,r,"leaders");s.leaders.push_back(std::move(r));}for(const auto& c:boundary::array(boundary::field(value,"causes","command_shock"),"causes")){MilitaryCommandShockCause r;dec(c,r,"causes");s.causes.push_back(std::move(r));}auto valid=wire(s);if(!valid.ok)return {false,{},valid.error};return {true,std::move(s),{}};}catch(const boundary::DecodeFailure& e){return {false,{},e.error};}}
Status visit(CodecVisitor& v,MilitaryCommandShockState& s){if(!(v.schema_features&military_command_shock_checkpoint_feature)||!(v.schema_features&military_rout_checkpoint_feature))return v.reject("MilitaryCommandShockPrerequisiteRequired");if(!v.reading()){auto valid=wire(s);if(!valid.ok)return v.reject(valid.error.original.code);}v.sequence("leaders",s.leaders,[](auto& child,auto& row){return walk(child,row);});v.sequence("causes",s.causes,[](auto& child,auto& row){return walk(child,row);});common_checkpoint::strings(v,"field_order",s.field_order);auto status=v.status();if(!status.ok)return status;auto valid=wire(s);return valid.ok?v.status():v.reject(valid.error.original.code);}
}
